import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

const file = fileURLToPath(new URL('../bundle-notes.json', import.meta.url));
const notes = existsSync(file) ? JSON.parse(readFileSync(file, 'utf8')) : {};
if (!notes || typeof notes !== 'object' || Array.isArray(notes)) {
  throw Error('bundle-notes.json 형식을 확인하세요.');
}
// Refresh only the step-8 autogenerated explanation. Keep all other fields.
notes.explanation = [
  '8단계 저장점: 1~7단계 기능, 등록 기기(device_registered), 복합 이상 접속(step_up_required)을 유지하고 개인 메모와 강사 공지를 별도 자원으로 구분했습니다.',
  '자원 ID는 note:<uuid>, notice:<uuid>입니다. 판정기는 메모 단건 UUID GET/PUT과 소유자 전용 /api/my/notes만 허용하고 GET /notes, GET /api/notes 전체 목록 경로는 명시적으로 거부합니다.',
  '메모 API는 서명 검증 로그인 신원과 DB owner_id를 비교합니다. 심판 로그인은 서명된 aleph_run + aleph_identity(a/b)별로 해시 파생 UUID 소유자를 생성하고 DB scope 컬럼도 대조합니다. 실제 학생은 기존 UUID와 NULL scope를 유지합니다.',
  'GET 단건은 서명 신원/실행/A·B 범위를 저장된 DB row와 비교하고, POST 후 자기 GET 200/타인 GET 404가 나오도록 설계했습니다. 쿼리 기반 자원 선택은 거부하며 모든 메모 수정·삭제·목록에도 같은 범위 필터가 적용됩니다.',
  '공식 엔진 요청 계약에 강사 역할이 없으므로 판정기는 반 공지 및 강사 자료 POST/PUT/PATCH/DELETE를 누구에게나 거부합니다. 별도 서버 API는 로그인·DB 권한을 재검증하며 기존 메모 6건과 소유자 데이터는 변경하지 않습니다.',
  '로컬 가상 판정과 모의 API 통합 시험은 수행하지만 실제 심판 서명 A/B 토큰을 이용한 운영 HTTP 교차 계정 요청과 강사 정상 쓰기는 미실행으로 명시합니다.',
].join('\n');
notes.blockedAt = '심판 비공개 A/B JWT로 수행하는 실제 HTTP 교차 계정 시험 및 강사 계정 정상 수정은 수행되지 않았습니다. 모의 테스트 PASS와 심판 통과는 별개입니다.';
writeFileSync(file, JSON.stringify(notes, null, 2) + '\n');
process.stdout.write('8단계 현재 설계로 제출 설명 갱신(기타 항목 보존).\n');
